from pathlib import Path
import pandas as pd,json
P=Path(__file__).resolve().parent
A=pd.read_csv(P/'prototypes_fixed4R_comparison.csv')
all_=pd.read_csv(P/'composite_prototypes_96.csv')
feat=json.loads((P/'condition_prevalence.json').read_text())
notes={'R01_PDL_weekly_discount':'Reversal: previous-day low sweep/reclaim within previous 60m + last-4-week discount + M5 bullish rejection (short mirror).','R02_daily_sweep_M15FVG':'Reversal: previous-day sweep/reclaim + active M15 FVG intersection + M5 directional close.','R03_week_sweep_H1FVG':'Reversal: previous-week sweep/reclaim + active H1 FVG + rejection.','R04_H1_fib_M15_trend':'Retracement: confirmed H1 0.618–0.786 fib zone + M15 trend agreement + M5 rejection.','R05_H1FVG_prior_15m_counter':'Reversal: active H1 FVG touch + completed M5 15m counter-move + M5 rejection.','R06_H4FVG_weekly_zone':'Reversal: H4 FVG + weekly premium/discount + M5 rejection.','R07_weighted_reversal':'Adaptive: >=2 of weekly half, daily sweep, H1 FVG, H1 fib + M5 rejection.','R08_HTF_zone_FVG_rejection':'Flexible: >=1 of weekly half or day sweep AND >=1 of H1/H4/M15 FVG AND M5 rejection.','C01_3TF_trend_breakout':'Continuation: H4+H1+M15 EMA20/50 aligned + 12×M5 high/low breakout.','C02_H1trend_M5FVG':'Continuation: H1/M15 trend + M5 FVG touch + directional M5 body.','C03_H1_fib_trend':'Continuation: confirmed H1 Fib retracement + H1 trend + M5 rejection.','C04_M15FVG_trend_engulf':'Continuation: M15 trend + active M15 FVG touch + M5 engulfing.','C05_adaptive_trend':'Adaptive continuation: >=1 H4/H1 trend, >=1 M15/M5 trend, M5 breakout or rejection.','R09_weekly_extreme_RSI':'Reversal: outer 20% of preceding 4 completed weeks range + M5 RSI14 extreme + rejection.','R10_day_sweep_M15trend':'Reversal/momentum: prior-day sweep/reclaim in previous hour + M15 trend alignment + M5 directional body.','C06_H4H1_M15FVG_displace':'Continuation: H4+H1 trend + M15 FVG + most-recent closed M15 displacement + M5 directional body.'}
assert len(notes)==16
cols=['playbook','train_n','train_avg_R','review_REUSED_n','review_REUSED_avg_R','review_REUSED_coverage_pct']
lines=['# Proof-of-concept playbooks — exploratory only','', 'All examples are symmetric LONG/SHORT. Signal M5 closes, entry at next available M1 open 06:00–20:00 Asia/Jerusalem. The 16 playbooks are **illustrative building blocks, not approved trading rules**.','', 'Baseline comparison uses common parameters: **1.5 × completed M5 ATR14 initial SL, fixed 4R TP, 120-minute max hold, assumed $0.35 roundtrip cost in XAUUSD price units**.','','| Playbook | Train trades | Train R/trade | Reused Apr–Sep 2026 trades | Reused R/trade | Reused daily coverage |','|---|---:|---:|---:|---:|---:|']
for _,r in A.iterrows():lines.append('| '+r.playbook+' | '+str(int(r.train_n))+' | '+f'{r.train_avg_R:+.3f}'+' | '+str(int(r.review_REUSED_n))+' | '+f'{r.review_REUSED_avg_R:+.3f}'+' | '+f'{r.review_REUSED_coverage_pct:.1f}%'+' |')
lines+=['','## Every recipe definition','']
for key,desc in notes.items():lines.extend(['### '+key,desc,''])
lines+=['## Critical limitations','','**The April–September 2026 period has already been used in previous strategy research, and is NOT an independent unseen holdout.** These are descriptive exploratory outcomes, not proof of a strategy edge. No prototype has validated +1R/trade. Train 2025-01–2026-03; later review 2026-04–2026-09.','', 'Do not sort by recent-period profit and then report it as unbiased performance. No genuine forward out-of-sample testing has been performed for these new composite rules.','', 'Bid-only OHLC feed; friction assumption $0.35 in price; M1 SL/TP collision resolved STOP first; no tick order, partial fills, spread or actual broker costs. Data gaps can force exit after 120 minutes; exceptions must be excluded/resolved before any live deployment.','', 'Entry/exit manager variants in `composite_prototypes_96.csv`, full trade logs in `prototype_trade_log.csv`.','']
(P/'PLAYBOOKS.md').write_text('\n'.join(lines),encoding='utf8')
summary={'m1_candles':760337,'signal_bars':feat['candidate_m5_closes'],'bank_conditions':len(feat['by_parameter']),'prototype_playbooks':len(notes),'prototype_configurations':len(all_),'reused_period_is_not_new_holdout':True,'positive_reused_fixed4':int((A.review_REUSED_avg_R>0).sum()),'over_1R_reused_fixed4':int((A.review_REUSED_avg_R>=1).sum()),'prototype_trades_all_configs':None}
(P/'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf8')
category=lambda k: ('Liquidity' if 'sweep' in k else 'FVG' if 'fvg_' in k else 'Fibonacci' if 'fib_' in k else 'Context' if ('weekly_' in k or k.startswith(('h1_','h4_','m15_','m5_up','m5_down'))) else 'M5 trigger')
with (P/'PARAMETER_DICTIONARY.md').open('w',encoding='utf8') as f:
    f.write('# Parameter bank — named fields and market-wide frequency\n\nCounts represent **completed M5 decision points 06:00–20:00 local time**, not 3×ATR or 4×ATR retrospectively successful legs. Signals can overlap.\n\n| Family | Feature ID | Bars with feature | % of 75,264 |\n|---|---|---:|---:|\n')
    for k,v in feat['by_parameter'].items():f.write(f'| {category(k)} | `{k}` | {v:,} | {v/feat["candidate_m5_closes"]*100:.2f}% |\n')
    f.write('''\n## Detailed calculations and caution
- Previous-day sweep/reclaim: M5 wick beyond the prior **trading-day** high/low and M5 close back through the level; `_last60m` means this happened in the previous 12 completed M5 bars, including the signal bar. Previous week analogous, Israeli weeks ending Sunday.
- Weekly premium/discount: above/below the midpoint of last four **fully completed Israel calendar weeks** (not the current week's final high/low). Outer 20% of this historic four-week range also provided.
- H1 swing fib: last confirmed H1 swing highs/lows with 2 completed H1 bars on each side; pivot confirmation is delayed 2 hours. Only the most recent two opposite confirmed pivots define the impulse; 0.618–0.786 area requires current price within that zone. This is NOT a verified ICT structural swing and is NOT proof of untouched 0.5.
- M15/H1/H4 trend: EMA20 greater/less than EMA50 on latest **completed** HTF candle. EMA trend and directional confirmation are highly correlated and must not be counted as independent evidence.
- FVG: lifecycle table from canonical archive; zone's `available_at` strictly precedes the signal M5 close and `invalidated_at` is later. Zone range overlaps current completed M5 candle's high-low, which does not prove a clean tradable bounce, and can introduce same-bar sequencing ambiguity.
- M5 rejection, engulfing, breakout and RSI14 are defined exactly in `build_bank.py` and use only completed bars.
- The M1 execution price is the **next M1 open** following M5 signal close, not a lookahead pivot low/high.
- Missing or incomplete bars and ambiguous OHLC order require tick verification for deployment.
''')
print('docs written')